using System;
using LittleLeo;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "EndTurnConditionSpecificDiceTierOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/EndTurnConditionSpecificDiceTierOmenData")]
public class EndTurnConditionSpecificDiceTierOmenData : OnSpecificDiceTierOmenData
{
	[SerializeField]
	protected EndOfTurnForEndTurnConditionOmenData endOfTurnForEndTurnConditionOmenData;

	[NonSerialized]
	protected OmenInstance omenInstance;

	public override void Initialize(OmenInstance omenInstance)
	{
		this.omenInstance = omenInstance;
		base.Initialize(omenInstance);
		endOfTurnForEndTurnConditionOmenData.Initialize(omenInstance);
		endOfTurnForEndTurnConditionOmenData.InitializeExternal(this);
		ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.RestartStartTurnOmens.Add(omenInstance);
		ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.RestartEndBattleOmens.Add(omenInstance);
	}

	public override void ActivateOmen(GameObject target = null)
	{
		ToggleAlreadyUsed(toggle: true);
		omenInstance.DisableOmen();
		omenInstance.ToggleOmenCounter(toggle: false);
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.RestartStartTurnOmens.Remove(omenInstance);
		ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.RestartEndBattleOmens.Remove(omenInstance);
	}

	public void ActivateBattleAction()
	{
		omenInstance.ActivateOmenFeedback();
		InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, 0.6f, delegate
		{
			OmenLogicActiveOmen(ActionValue);
		});
	}

	public override string OmenConvertedDescription()
	{
		return endOfTurnForEndTurnConditionOmenData.GetEndOfPlayerTurnLocalizedDescription() + base.localizationManager.GetLocalizedSpace() + Smart.Format(GetOmenRawLocalizedDescription(), GetOmenConvertedDescriptionBattleAction().LowercaseFirst());
	}
}
